"""Fast exact solver for uniform optimal-transport instances."""
import numpy as np
from numba import njit

@njit(cache=True)
def _assign(C):
    n=C.shape[0]
    # Euclidean random instances are local. Keep all short edges; the generous
    # cutoff still makes bidding much cheaper than scanning the dense graph.
    cutoff=.40
    deg=np.zeros(n,np.int32)
    for i in range(n):
        for j in range(n):
            if C[i,j] < cutoff: deg[i]+=1
    mx=np.max(deg)
    ix=np.empty((n,mx),np.int32)
    for i in range(n):
        z=0
        for j in range(n):
            if C[i,j] < cutoff:
                ix[i,z]=j; z+=1
    price=np.zeros(n); owner=np.full(n,-1,np.int32); ass=np.full(n,-1,np.int32)
    eps=.02
    while eps>1e-10:
        owner[:]=-1; ass[:]=-1
        stack=np.arange(n,dtype=np.int32); top=n
        while top:
            top-=1; i=stack[top]; best=1e100; second=1e100; bj=-1
            for z in range(deg[i]):
                j=ix[i,z]; v=C[i,j]+price[j]
                if v<best: second=best; best=v; bj=j
                elif v<second: second=v
            old=owner[bj]; price[bj]+=second-best+eps
            owner[bj]=i; ass[i]=bj
            if old>=0:
                ass[old]=-1; stack[top]=old; top+=1
        eps*=.1
    return ass

class Solver:
    def solve(self, problem, **kwargs):
        a=np.asarray(problem['source_weights']); b=np.asarray(problem['target_weights'])
        C=np.asarray(problem['cost_matrix']); n,m=C.shape
        if n==m and np.all(a==a[0]) and np.all(b==b[0]) and abs(a[0]-b[0])<1e-15:
            cols=_assign(C)
            G=np.zeros((n,n)); G[np.arange(n),cols]=a[0]
            return {'transport_plan':G}
        import ot
        return {'transport_plan':ot.lp.emd(a,b,np.ascontiguousarray(C,dtype=np.float64),check_marginals=False)}
